brnz,pt %l3, sync_init_1_11
lduw [%o5+4], %l3 ! delay slot
sync_init_2_11:
lduw [%o5], %l3
sub %l3, 1, %l6
cas [%o5], %l3, %l6
cmp %l3, %l6
bne,pt %xcc, sync_init_2_11
nop
membar #Sync
sync_init_3_11:
lduw [%o5], %l3 ! delay slot
brnz,pt %l3, sync_init_3_11
nop
!-- end of sync_init ---


